import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
  JxAlert,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  city: string;
  street: string;
  comment: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  city: '',
  street: '',
  comment: '',
};

export default function RegistrationWizard({
  onSubmit,
}: {
  onSubmit: (data: RegistrationData) => void;
}) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);
  const [touched, setTouched] = useState(false);

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const nameError = !data.name.trim() ? 'Укажите имя' : undefined;
  const emailError = !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;
  const cityError = !data.city.trim() ? 'Укажите город' : undefined;
  const streetError = !data.street.trim() ? 'Укажите улицу и дом' : undefined;

  const stepErrors = step === 0 ? [nameError, emailError] : step === 1 ? [cityError, streetError] : [];
  const stepValid = stepErrors.every((error) => !error);
  const isLast = step === steps.length - 1;

  const goNext = () => {
    if (!stepValid) {
      setTouched(true);
      return;
    }
    setTouched(false);
    setStep((current) => Math.min(current + 1, steps.length - 1));
  };

  const goBack = () => {
    setTouched(false);
    setStep((current) => Math.max(current - 1, 0));
  };

  const submit = () => onSubmit(data);

  return (
    <form
      onSubmit={(event) => {
        event.preventDefault();
        if (isLast) submit();
        else goNext();
      }}
      style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            autoComplete="name"
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
            errorText={touched ? nameError : undefined}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            autoComplete="email"
            helperText="Сюда придёт подтверждение регистрации"
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={touched ? emailError : undefined}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Город"
            required
            autoComplete="address-level2"
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
            errorText={touched ? cityError : undefined}
          />
          <JxInputField
            label="Улица и дом"
            required
            autoComplete="street-address"
            value={data.street}
            onChange={(event) => set('street', event.target.value)}
            errorText={touched ? streetError : undefined}
          />
          <JxTextareaField
            label="Комментарий к доставке"
            rows={3}
            maxLength={300}
            value={data.comment}
            onChange={(event) => set('comment', event.target.value)}
            helperText={`${data.comment.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxAlert intent="info" title="Проверьте данные">
            После отправки изменить анкету можно будет только через поддержку.
          </JxAlert>
          <JxDivider label="Контакты" />
          <dl style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 12rem) minmax(0, 1fr)', gap: '8px 16px', margin: 0 }}>
            <dt style={{ color: 'var(--jx-text-2)' }}>Имя</dt>
            <dd style={{ margin: 0, wordBreak: 'break-word' }}>{data.name}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Почта</dt>
            <dd style={{ margin: 0, wordBreak: 'break-word' }}>{data.email}</dd>
          </dl>
          <JxDivider label="Адрес" />
          <dl style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 12rem) minmax(0, 1fr)', gap: '8px 16px', margin: 0 }}>
            <dt style={{ color: 'var(--jx-text-2)' }}>Город</dt>
            <dd style={{ margin: 0, wordBreak: 'break-word' }}>{data.city}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Улица и дом</dt>
            <dd style={{ margin: 0, wordBreak: 'break-word' }}>{data.street}</dd>
            <dt style={{ color: 'var(--jx-text-2)' }}>Комментарий</dt>
            <dd style={{ margin: 0, wordBreak: 'break-word' }}>
              {data.comment.trim() ? data.comment : '—'}
            </dd>
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton type="button" variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {isLast ? (
          <JxButton type="submit" variant="primary">
            Отправить
          </JxButton>
        ) : (
          <JxButton type="submit" variant="primary">
            Дальше
          </JxButton>
        )}
      </div>
    </form>
  );
}

